using System.Globalization;
using Engine.Components;
using Engine.Entities;
using Engine.Logic;
using Engine.Recources;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Input;
using Vista;

namespace Engine.Scripting;

/// <summary>
/// The AudioTest sample scene (Content/Scenes/AudioTest.obsc, generated by Tools/Scripts/generate_audio_test_scene.py).
/// Runs on the Main Camera next to Freecam; the camera is the listener. Five stations:
///   Stereo   (x = 0)    1  2D left/right check: low pips LEFT, then high pips RIGHT
///                       2  2D pulse whose Stereo Pan sweeps left - right
///                       3  3D emitter orbiting the listening spot: front, left, behind, right
///   Distance (x = 60)   a beacon with posts at its Min (3 m), 10 m and Max (25 m) distance
///                       R  cycle the Rolloff curve        T  shuttle the beacon away and back
///   Reverb   (x < -40)  Bathroom, Concert Hall (Padded Booth nested inside), Sewer Tunnel, each a Reverb Zone
///                       F  clap (2D, at the listener)     C  room echo emitter claps on / off
///   Walls    (-20, 12)  a radio in a closed wooden hut behind a free wall: 2 walls, walk round the wall (1), to the door (0)
///                       M  cycle the free wall's Sound Material (Concrete, Brick, Wood, Glass, Metal, Fabric...)
///   Doppler  (0, -60)   4  an engine racing past along y = -50     [ ]  slower / faster
///   5 / 6 / 7 / 8 / 9 jump to the Doppler / Walls / Stereo / Distance / Reverb station.
/// </summary>
public sealed class AudioTestSceneScript : ScriptBehaviour
{
    public const string ScriptId = "audio-test";

    private const string DocumentPath = "UI/AudioTest";
    private const string ClapClip = "Audio/Test/clap.wav";

    public static readonly Vector3 ListenSpot = new(0, 0, 1.7f);
    public static readonly (Keys Key, string Name, Vector3 Position)[] Stations =
    {
        (Keys.D5, "Doppler", new Vector3(0, -60, 1.7f)), (Keys.D6, "Walls", new Vector3(-20, 12, 1.7f)),
        (Keys.D7, "Stereo", ListenSpot), (Keys.D8, "Distance", new Vector3(60, -42, 1.7f)), (Keys.D9, "Reverb", new Vector3(-48, -3, 1.7f)),
    };
    /// <summary>The racer drives along y = -50 from x = -RacerTrack to +RacerTrack, then starts over.</summary>
    public const float RacerTrack = 80;

    [Range(2, 30), Tooltip("Seconds per orbit of the Orbiting Emitter.")]
    public float OrbitPeriod = 8;
    [Range(1, 10), Tooltip("Orbit radius around the listening spot, in metres.")]
    public float OrbitRadius = 4;
    [Range(2, 30), Tooltip("Seconds per left - right - left sweep of Pan Sweep.")]
    public float PanPeriod = 6;
    [Range(4, 60), Tooltip("Seconds for the beacon to go out to 40 m and back when shuttling.")]
    public float ShuttlePeriod = 16;
    [Range(0.5f, 10), Tooltip("Seconds between room echo claps.")]
    public float EchoInterval = 1.6f;
    [Tooltip("The nearest room's echo emitter claps every Echo Interval.")]
    public bool AutoEcho = true;
    [Range(5, 100), Tooltip("Doppler Racer speed in m/s (35 m/s = 126 km/h; sound is 340 m/s).")]
    public float RacerSpeed = 35;

    private UIManager _ui;
    private BasicEntity _stereoCheck, _panSweep, _orbit, _beacon, _radio, _racer, _freeWall;
    private SoundMaterial _freeWallHome;

    /// <summary>The materials M steps through, with the colour the free wall takes for each.</summary>
    public static readonly (SoundMaterial Material, Vector3 Color, float Metallic)[] WallMaterials =
    {
        (SoundMaterial.Concrete, new Vector3(0.5f, 0.5f, 0.52f), 0), (SoundMaterial.Brick, new Vector3(0.6f, 0.25f, 0.18f), 0),
        (SoundMaterial.Stone, new Vector3(0.42f, 0.4f, 0.37f), 0), (SoundMaterial.Plaster, new Vector3(0.88f, 0.86f, 0.82f), 0),
        (SoundMaterial.Wood, new Vector3(0.55f, 0.38f, 0.2f), 0), (SoundMaterial.Metal, new Vector3(0.7f, 0.72f, 0.75f), 1),
        (SoundMaterial.Glass, new Vector3(0.6f, 0.8f, 0.85f), 0), (SoundMaterial.Fabric, new Vector3(0.45f, 0.15f, 0.2f), 0),
        (SoundMaterial.Foliage, new Vector3(0.2f, 0.45f, 0.15f), 0), (SoundMaterial.Default, new Vector3(0.75f, 0.75f, 0.75f), 0),
    };
    private readonly List<BasicEntity> _echoEmitters = new();
    private Vector3 _beaconHome;
    private float _time, _shuttleTime, _echoTimer;
    private bool _shuttle;

    public override void Start()
    {
        _ui = GameUI.Open(DocumentPath);
        _stereoCheck = FindGameObject("Stereo Check (2D)");
        _panSweep = FindGameObject("Pan Sweep (2D)");
        _orbit = FindGameObject("Orbiting Emitter");
        _beacon = FindGameObject("Distance Beacon");
        _radio = FindGameObject("Hut - Radio");
        _racer = FindGameObject("Doppler Racer");
        _freeWall = FindGameObject("Walls - Free Wall");
        _freeWallHome = _freeWall?.GetComponent<PhysicsComponent>()?.SoundMaterial ?? SoundMaterial.Default;
        _beaconHome = _beacon?.Position ?? Vector3.Zero;
        _echoEmitters.Clear();
        foreach (BasicEntity entity in GameFlow.SceneLogic?.ActiveScene?.BasicEntities ?? new List<BasicEntity>())
            if (entity.Name.EndsWith("Echo Emitter", StringComparison.Ordinal)) _echoEmitters.Add(entity);
        _time = _shuttleTime = _echoTimer = 0;
        _shuttle = false;
    }

    public override void Stop()
    {
        SetWallMaterial(_freeWallHome);
        if (_beacon != null) _beacon.Position = _beaconHome;
        GameUI.Close(_ui);
        _ui = null;
    }

    public override void Update()
    {
        if (!DebugScreen.ConsoleOpen) HandleInput();
        _time += DeltaTime;

        // Orbit counter-clockwise seen from above: in front (+Y), then left (-X), behind, right.
        if (_orbit != null)
        {
            float angle = _time / MathHelper.Max(OrbitPeriod, 0.5f) * MathHelper.TwoPi;
            _orbit.Position = ListenSpot + OrbitRadius * new Vector3(-MathF.Sin(angle), MathF.Cos(angle), 0);
        }
        if (AudioOf(_panSweep) is { } sweep) sweep.Pan = MathF.Sin(_time / MathHelper.Max(PanPeriod, 0.5f) * MathHelper.TwoPi);
        if (_beacon != null && _shuttle)
        {
            _shuttleTime += DeltaTime;
            float out01 = 0.5f - 0.5f * MathF.Cos(_shuttleTime / MathHelper.Max(ShuttlePeriod, 1) * MathHelper.TwoPi);
            _beacon.Position = _beaconHome - new Vector3(0, 40 * out01, 0);
        }
        if (_racer != null && AudioOf(_racer)?.IsPlaying == true)
        {
            Vector3 p = _racer.Position + new Vector3(RacerSpeed * DeltaTime, 0, 0);
            // Back to the start in one jump: AudioManager treats it as a teleport, not a 9000 m/s Doppler shift.
            if (p.X > RacerTrack) p.X = -RacerTrack;
            _racer.Position = p;
        }
        if (AutoEcho)
        {
            _echoTimer += DeltaTime;
            if (_echoTimer >= EchoInterval)
            {
                _echoTimer = 0;
                BasicEntity echo = NearestEcho();
                AudioOf(echo)?.Play(echo);
            }
        }
        UpdateHud();
    }

    private void HandleInput()
    {
        if (GameInput.WasPressed(Keys.D1)) Toggle(_stereoCheck);
        if (GameInput.WasPressed(Keys.D2)) Toggle(_panSweep);
        if (GameInput.WasPressed(Keys.D3)) Toggle(_orbit);
        if (GameInput.WasPressed(Keys.D4)) Toggle(_racer);
        if (GameInput.WasPressed(Keys.M) && _freeWall?.GetComponent<PhysicsComponent>() is { } wall)
        {
            int i = Array.FindIndex(WallMaterials, m => m.Material == wall.SoundMaterial);
            SetWallMaterial(WallMaterials[(i + 1) % WallMaterials.Length].Material);
        }
        if (GameInput.WasPressed(Keys.OemOpenBrackets)) RacerSpeed = MathF.Max(5, RacerSpeed - 5);
        if (GameInput.WasPressed(Keys.OemCloseBrackets)) RacerSpeed = MathF.Min(100, RacerSpeed + 5);
        if (GameInput.WasPressed(Keys.R) && AudioOf(_beacon) is { } beacon)
            beacon.Rolloff = (AudioRolloff)(((int)beacon.Rolloff + 1) % Enum.GetValues<AudioRolloff>().Length);
        if (GameInput.WasPressed(Keys.T))
        {
            _shuttle = !_shuttle;
            if (!_shuttle && _beacon != null) _beacon.Position = _beaconHome;
            _shuttleTime = 0;
        }
        if (GameInput.WasPressed(Keys.F)) PlaySound(ClapClip);
        if (GameInput.WasPressed(Keys.C)) AutoEcho = !AutoEcho;
        foreach (var station in Stations)
            if (GameInput.WasPressed(station.Key)) Position = station.Position;
    }

    /// <summary>Gives the free wall <paramref name="material"/> for sound, and its look.</summary>
    public void SetWallMaterial(SoundMaterial material)
    {
        if (_freeWall?.GetComponent<PhysicsComponent>() is not { } physics) return;
        physics.SoundMaterial = material;
        int i = Array.FindIndex(WallMaterials, m => m.Material == material);
        if (i < 0 || _freeWall.GetComponent<MaterialComponent>() is not { } look) return;
        (_, Vector3 color, float metallic) = WallMaterials[i];
        look.Red = color.X;
        look.Green = color.Y;
        look.Blue = color.Z;
        look.Metallic = metallic;
        look.OnChanged(_freeWall);
    }

    private static AudioComponent AudioOf(BasicEntity entity) => entity?.GetComponent<AudioComponent>();

    private static void Toggle(BasicEntity entity)
    {
        if (AudioOf(entity) is not { } audio) return;
        if (audio.IsPlaying) audio.OnStop();
        else audio.Play(entity);
    }

    private BasicEntity NearestEcho()
    {
        BasicEntity nearest = null;
        float best = 25;
        foreach (BasicEntity emitter in _echoEmitters)
        {
            float distance = Vector3.Distance(emitter.Position, Position);
            if (distance < best) (nearest, best) = (emitter, distance);
        }
        return nearest;
    }

    /// <summary>The volume FMOD's <paramref name="rolloff"/> curve gives at <paramref name="distance"/> (0..1).</summary>
    public static float ExpectedVolume(AudioRolloff rolloff, float distance, float min, float max)
    {
        if (distance <= min) return 1;
        float inverse = min / MathF.Min(distance, max);
        float linear = MathHelper.Clamp(1 - (distance - min) / MathF.Max(max - min, 1e-3f), 0, 1);
        return rolloff switch
        {
            AudioRolloff.Linear => linear,
            AudioRolloff.LinearSquare => linear * linear,
            AudioRolloff.InverseTapered => MathF.Min(inverse, linear * linear),
            _ => inverse,
        };
    }

    /// <summary>
    /// The pitch factor Doppler gives a sound at <paramref name="source"/> moving at <paramref name="sourceVelocity"/>
    /// heard at <paramref name="listener"/> moving at <paramref name="listenerVelocity"/>: above 1 while they close in.
    /// </summary>
    public static float ExpectedPitch(Vector3 source, Vector3 sourceVelocity, Vector3 listener, Vector3 listenerVelocity, float level = 1)
    {
        Vector3 toListener = listener - source;
        if (toListener.LengthSquared() < 1e-6f) return 1;
        toListener.Normalize();
        float c = AudioManager.SpeedOfSound;
        float sourceTowards = Vector3.Dot(sourceVelocity, toListener) * level;
        float listenerTowards = -Vector3.Dot(listenerVelocity, toListener) * level;
        return (c + listenerTowards) / MathF.Max(c - sourceTowards, 1);
    }

    private void UpdateHud()
    {
        if (_ui == null) return;
        CultureInfo c = CultureInfo.InvariantCulture;
        Vector3 at = Position;
        string station = Stations.MinBy(s => Vector3.DistanceSquared(s.Position, at)).Name;
        _ui.SetText("#station", Audio.IsAvailable
            ? $"{station} station"
            : $"{station} station  ·  AUDIO OFF: fmod.dll missing or the wrong version (see the log)");

        var zones = ReverbZoneComponent.ActiveZones;
        _ui.SetText("#reverb", zones.Count == 0
            ? "Reverb: none (outdoors)"
            : "Reverb: " + string.Join("  >  ", zones.Select(z =>
                $"{z.Zone.Name.Replace(" - Reverb Zone", "")} {(z.Weight * 100).ToString("0", c)}%")));
        FMOD.REVERB_PROPERTIES reverb = Audio.Reverb;
        _ui.SetText("#reverb-detail", zones.Count == 0 ? "Walk into a room (9 jumps there) and press F to clap"
            : $"Decay {(reverb.DecayTime / 1000).ToString("0.0", c)} s  ·  wet {reverb.WetLevel.ToString("0.0", c)} dB  ·  " +
              $"early {reverb.EarlyDelay.ToString("0", c)} ms  ·  high cut {reverb.HighCut.ToString("0", c)} Hz");

        string Onoff(BasicEntity e) => AudioOf(e)?.IsPlaying == true ? "on" : "off";
        string side = "";
        if (_orbit != null)
        {
            Vector3 local = _orbit.Position - at;
            float right = Vector3.Dot(local, Right), front = Vector3.Dot(local, Forward);
            side = MathF.Abs(right) > MathF.Abs(front) ? (right > 0 ? "right" : "left") : (front > 0 ? "front" : "behind");
        }
        _ui.SetText("#stereo", $"1 L/R check {Onoff(_stereoCheck)}  ·  2 pan sweep {Onoff(_panSweep)} " +
                               $"({(AudioOf(_panSweep)?.Pan ?? 0).ToString("+0.00;-0.00", c)})  ·  3 orbit {Onoff(_orbit)} ({side})");

        if (AudioOf(_beacon) is { } beacon)
        {
            float distance = Vector3.Distance(_beacon.Position, at);
            float volume = ExpectedVolume(beacon.Rolloff, distance, beacon.MinDistance, beacon.MaxDistance);
            _ui.SetText("#distance", $"Beacon {distance.ToString("0.0", c)} m  ·  {beacon.Rolloff}  ·  " +
                                     $"min {beacon.MinDistance.ToString("0", c)} / max {beacon.MaxDistance.ToString("0", c)}  ·  " +
                                     $"volume {(volume * 100).ToString("0", c)}%{(_shuttle ? "  ·  shuttling" : "")}");
        }
        _ui.SetText("#echo", $"Room echo claps {(AutoEcho ? "on" : "off")}  ·  walls muffle {(Audio.WallOcclusion * 100).ToString("0", c)}% each");

        string walls = "Radio off";
        if (AudioOf(_radio)?.Emitter is { } radio)
        {
            SoundMaterial wallMaterial = _freeWall?.GetComponent<PhysicsComponent>()?.SoundMaterial ?? SoundMaterial.Default;
            walls = $"Radio: {radio.Walls.ToString("0.0", c)} walls  ·  quieter {(radio.Occlusion * 100).ToString("0", c)}%  ·  " +
                    $"duller {(radio.Dullness * 100).ToString("0", c)}%  ·  M free wall: {wallMaterial}";
        }
        _ui.SetText("#walls", walls);

        string doppler = $"4 racer off  ·  [ ] speed {RacerSpeed.ToString("0", c)} m/s";
        if (AudioOf(_racer) is { } racerAudio && racerAudio.Emitter is { } racer)
        {
            float pitch = ExpectedPitch(racer.Position, racer.Velocity, at, Audio.ListenerVelocity, racerAudio.DopplerLevel);
            doppler = $"4 racer {racer.Velocity.Length().ToString("0", c)} m/s, {Vector3.Distance(racer.Position, at).ToString("0", c)} m  ·  " +
                      $"pitch x{pitch.ToString("0.000", c)} ({(pitch >= 1 ? "approaching" : "leaving")})  ·  [ ] speed";
        }
        _ui.SetText("#doppler", doppler);
    }
}
